head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#f7f3e9" value="#f7f3e9"/><Variable name="page.text" description="Text color" type="color" default="#203b39" value="#203b39"/><Variable name="theme.accent" description="Accent color" type="color" default="#a84329" value="#a84329"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:'Playfair Display', Georgia, serif;--body:Arial, sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
.site-header{padding:25px 5%;display:flex;align-items:center;justify-content:space-between}.brand{font:bold 27px 'Playfair Display', Georgia,serif;letter-spacing:-1px}nav{display:flex;gap:28px;font-size:11px}.travel-hero{position:relative;min-height:680px;color:white;isolation:isolate;overflow:hidden}.travel-hero>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2}.travel-shade{position:absolute;inset:0;background:linear-gradient(90deg,rgba(9,32,32,.63),rgba(9,32,32,.04)),linear-gradient(0deg,rgba(9,32,32,.4),transparent 50%);z-index:-1}.travel-title{padding:75px 7%}.travel-title>p{font-size:9px;letter-spacing:2px}.travel-title h1{font:normal clamp(73px,9vw,120px)/.92 'Playfair Display', Georgia,serif;letter-spacing:-5px;margin:58px 0 30px}.travel-title>span{font-size:14px;line-height:1.75}.travel-hero-link{position:absolute;bottom:42px;right:7%;font-size:12px;border-bottom:1px solid;padding-bottom:8px}.travel-intro{padding:60px 7%;display:grid;grid-template-columns:1fr 2fr 1.5fr;gap:40px;align-items:start}.travel-intro>span{font-size:9px;line-height:1.6;letter-spacing:1.5px;color:#a84329}.travel-intro h2{font:normal 39px/1.1 'Playfair Display', Georgia,serif;letter-spacing:-1px;margin:0}.travel-intro p{font-size:13px;line-height:1.9;margin:0}.travel-route{margin:10px 7% 65px;display:grid;grid-template-columns:1.4fr 1fr;gap:55px;align-items:center}.travel-route figure{margin:0}.travel-route svg{width:100%;display:block}.travel-route figcaption{font-size:8px;letter-spacing:1.2px;margin-top:12px}.travel-kicker{font-size:9px;letter-spacing:1.7px;color:#a84329}.travel-route h2{font:normal 42px/1.1 'Playfair Display', Georgia,serif;letter-spacing:-1px}.travel-route p:not(.travel-kicker){font-size:13px;line-height:1.8}.travel-route a{display:inline-block;font-size:11px;border-bottom:1px solid;padding-bottom:5px;margin-top:15px}.travel-topics{padding:28px 7%;background:#e4e8d9;display:flex;align-items:center;justify-content:space-between;gap:25px}.travel-topics>span{font-size:9px;letter-spacing:1px;max-width:120px}.travel-topics a{font:20px 'Playfair Display', Georgia,serif;white-space:nowrap}.travel-topics b{font-weight:normal;color:#a84329;margin-left:12px}.latest{padding:55px 7%}.section-heading{font:normal 37px 'Playfair Display', Georgia,serif;margin-bottom:35px}.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:30px}.post-media{aspect-ratio:4/3;object-fit:cover;background:#c4d8cf}.post-meta{font-size:9px;text-transform:uppercase;letter-spacing:1px;color:#a84329}.post-title{font:normal 27px/1.15 'Playfair Display', Georgia,serif}.post-excerpt{font-size:13px;line-height:1.7}.travel-postcard{background:#203b39;color:#f7f3e9;text-align:center;padding:65px 10%}.travel-postcard .travel-kicker{color:#dfb888}.travel-postcard h2{font:normal 47px/1.1 'Playfair Display', Georgia,serif;letter-spacing:-1px}.travel-postcard p:not(.travel-kicker){font-size:13px;line-height:1.9;max-width:450px;margin:auto}.travel-postcard a{display:inline-block;font-size:11px;border-bottom:1px solid;margin-top:28px;padding-bottom:6px}.site-footer{display:flex;align-items:center;justify-content:space-between;gap:22px;padding:30px 5%;font-size:10px}.site-footer strong{font:bold 23px 'Playfair Display', Georgia,serif}a:hover,a:focus-visible{text-decoration:underline}@media(max-width:700px){.site-header{flex-direction:column;gap:20px}.travel-hero{min-height:620px}.travel-title h1{font-size:88px}.travel-intro{grid-template-columns:1fr;gap:25px;padding:40px 7%}.travel-route{grid-template-columns:1fr;gap:20px}.travel-topics{align-items:start;flex-direction:column;gap:20px}.travel-topics>span{max-width:none}.posts-grid{grid-template-columns:1fr}.travel-postcard h2{font-size:36px}.site-footer{flex-direction:column}}
:focus-visible{outline:2px solid currentColor;outline-offset:5px}img,svg{max-width:100%}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
h1,h2,h3{font-family:'Playfair Display', Georgia, serif}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
